import React from 'react';
import { render } from '@testing-library/react-native';
import { Dimensions } from 'react-native';
import SimpleAddButtons from '../../src/components/ui/SimpleAddButtons';
import ReceiptSavedSnackbar from '../../src/components/ui/ReceiptSavedSnackbar';
import ReceiptCard from '../../src/components/ui/ReceiptCard';
import DashboardScreen from '../../src/screens/DashboardScreen';
import BottomNavigator from '../../src/navigation';

// Ensure jest-native matchers are available (if not already set up)
import '@testing-library/jest-native/extend-expect';

// Helper to flatten style arrays into a single object.
function flattenStyle(style: any): any {
  if (!style) return {};
  if (Array.isArray(style)) {
    return Object.assign({}, ...style);
  }
  return style;
}

// Mock the device dimensions to the target phone size.
beforeAll(() => {
  jest.spyOn(Dimensions, 'get').mockImplementation((dim) => {
    if (dim === 'window') {
      return { width: 390, height: 844, scale: 2, fontScale: 2 };
    }
    return { width: 0, height: 0, scale: 1, fontScale: 1 };
  });
});

describe('Dashboard layout', () => {
  it('SimpleAddButtons is absolutely positioned above the bottom tab bar', () => {
    const { getByTestId } = render(<SimpleAddButtons />);
    const container = getByTestId('simple-add-buttons');

    // The component should be absolutely positioned.
    expect(container).toHaveStyle({ position: 'absolute' });

    const style = flattenStyle(container.props.style);
    // Bottom offset must be enough to sit above the tab bar (56 dp) plus safe‑area padding.
    expect(style.bottom).toBeGreaterThanOrEqual(72);
  });

  it('ReceiptSavedSnackbar is absolutely positioned and sits above the tab bar when visible', () => {
    const { getByTestId } = render(
      <ReceiptSavedSnackbar visible={true} message="Receipt saved" />
    );
    const snackbar = getByTestId('receipt-saved-snackbar');

    expect(snackbar).toHaveStyle({ position: 'absolute' });

    const style = flattenStyle(snackbar.props.style);
    expect(style.bottom).toBeGreaterThanOrEqual(72);
  });

  it('ReceiptCard displays the receipt amount', () => {
    const receipt = {
      id: 'r1',
      amount: 123.45,
      date: '2023-01-01',
      category: 'Supplies',
      type: 'expense',
      notes: '',
    };

    const { getByText } = render(<ReceiptCard receipt={receipt} />);
    // The amount should appear in the rendered text (currency symbol is optional).
    expect(getByText(/123\.45/)).toBeTruthy();
  });

  it('DashboardScreen recent‑activity list has bottom padding to avoid FAB overlap', async () => {
    const { getByTestId } = render(<DashboardScreen />);
    // The ScrollView that holds recent activity rows is identified by this test‑id.
    const list = await getByTestId('recent-activity-list');

    const style = flattenStyle(list.props.contentContainerStyle);
    // The paddingBottom should be large enough to keep the last row visible above the FABs.
    expect(style.paddingBottom).toBeGreaterThanOrEqual(80);
  });

  it('bottom tab bar labels are fully visible on a 390×844 screen', () => {
    const { getByText } = render(<BottomNavigator />);
    const labels = ['Dashboard', 'Receipts', 'Mileage', 'Settings'];
    labels.forEach((label) => {
      expect(getByText(label)).toBeTruthy();
    });
  });
});
