/**
 * Acceptance tests for the Dashboard layout fix.
 *
 * These tests verify, without using any UI‑testing library beyond what the
 * project already depends on, that:
 *   1. The FAB add‑buttons are absolutely positioned above the bottom tab bar.
 *   2. The “Receipt saved” snackbar is also absolutely positioned and does not
 *      sit under the tab bar.
 *   3. A ReceiptCard displays the receipt amount (as required by the design).
 *   4. The DashboardScreen’s recent‑activity ScrollView has enough bottom
 *      padding so the list never scrolls over the FABs.
 *   5. The bottom‑tab navigator contains the four expected labels.
 *
 * The tests use `react-test-renderer`, which is already present as a dev
 * dependency of the Expo template (via `jest-expo`). No additional packages are
 * introduced.
 */

import React from 'react';
import TestRenderer from 'react-test-renderer';
import { Text, ScrollView } from 'react-native';

// Components under test
import SimpleAddButtons from '../../src/components/ui/SimpleAddButtons';
import ReceiptSavedSnackbar from '../../src/components/ui/ReceiptSavedSnackbar';
import ReceiptCard from '../../src/components/ui/ReceiptCard';
import DashboardScreen from '../../src/screens/DashboardScreen';
import Navigation from '../../src/navigation'; // default export is the navigation container

/**
 * Flattens a React Native style prop that may be an object, an array of objects,
 * or a nested array. Returns a plain object with the merged keys.
 */
function flattenStyle(style: any): any {
  if (!style) return {};
  if (Array.isArray(style)) {
    return Object.assign({}, ...style.map(flattenStyle));
  }
  return style;
}

/**
 * Mock device dimensions to the target phone size (390 × 844 dp). This is needed
 * because some components compute layout values from `Dimensions.get('window')`.
 */
beforeAll(() => {
  const { Dimensions } = require('react-native');
  jest.spyOn(Dimensions, 'get').mockImplementation((dim: string) => {
    if (dim === 'window') {
      return { width: 390, height: 844, scale: 2, fontScale: 2 };
    }
    // fallback for other dimensions
    return { width: 0, height: 0, scale: 1, fontScale: 1 };
  });
});

describe('Dashboard layout', () => {
  test('SimpleAddButtons is absolutely positioned above the tab bar', () => {
    const renderer = TestRenderer.create(<SimpleAddButtons />);
    // Find any node that has a style with position: 'absolute'
    const absoluteNodes = renderer.root.findAll(
      node => node.props?.style && flattenStyle(node.props.style).position === 'absolute'
    );
    expect(absoluteNodes.length).toBeGreaterThan(0);

    // At least one absolute node should define a bottom offset that leaves room for the
    // 56 dp tab bar plus a safe‑area inset (≈16 dp). We require ≥ 72 dp.
    const hasSufficientBottom = absoluteNodes.some(node => {
      const bottom = flattenStyle(node.props.style).bottom;
      return typeof bottom === 'number' && bottom >= 72;
    });
    expect(hasSufficientBottom).toBe(true);
  });

  test('ReceiptSavedSnackbar is absolutely positioned and sits above the tab bar when visible', () => {
    const renderer = TestRenderer.create(
      <ReceiptSavedSnackbar visible={true} message="Receipt saved" />
    );
    const absoluteNodes = renderer.root.findAll(
      node => node.props?.style && flattenStyle(node.props.style).position === 'absolute'
    );
    expect(absoluteNodes.length).toBeGreaterThan(0);

    const hasSufficientBottom = absoluteNodes.some(node => {
      const bottom = flattenStyle(node.props.style).bottom;
      return typeof bottom === 'number' && bottom >= 72;
    });
    expect(hasSufficientBottom).toBe(true);
  });

  test('ReceiptCard displays the receipt amount', () => {
    const receipt = {
      id: 'r1',
      amount: 123.45,
      date: '2023-01-01',
      category: 'Supplies',
      type: 'expense',
      notes: '',
    };
    const renderer = TestRenderer.create(<ReceiptCard receipt={receipt} />);
    // Look for any Text node whose rendered string contains the amount.
    const amountTexts = renderer.root.findAll(node => {
      return node.type === Text && typeof node.props?.children === 'string' && node.props.children.includes('123.45');
    });
    expect(amountTexts.length).toBeGreaterThan(0);
  });

  test('DashboardScreen recent‑activity list has bottom padding to avoid FAB overlap', () => {
    const renderer = TestRenderer.create(<DashboardScreen />);
    // Find the ScrollView that renders the recent activity list.
    const scrollViews = renderer.root.findAll(node => node.type === ScrollView);
    expect(scrollViews.length).toBeGreaterThan(0);

    // Assume the first ScrollView is the recent‑activity list.
    const scrollViewProps = scrollViews[0].props;
    const containerStyle = flattenStyle(scrollViewProps.contentContainerStyle);

    // The design adds enough padding to keep the last row visible above the FABs.
    // We enforce at least 80 dp (56 dp tab bar + 24 dp spacing).
    const paddingBottom = containerStyle.paddingBottom;
    expect(typeof paddingBottom).toBe('number');
    expect(paddingBottom).toBeGreaterThanOrEqual(80);
  });

  test('bottom tab bar labels are present and fully visible on a 390×844 screen', () => {
    const renderer = TestRenderer.create(<Navigation />);
    // Collect all rendered strings from Text nodes.
    const textNodes = renderer.root.findAll(node => node.type === Text);
    const renderedTexts = textNodes
      .map(node => node.props?.children)
      .filter(child => typeof child === 'string') as string[];

    const expectedLabels = ['Dashboard', 'Receipts', 'Mileage', 'Settings'];
    expectedLabels.forEach(label => {
      expect(renderedTexts).toContain(label);
    });
  });
});
