/**
 * Acceptance tests for the Dashboard layout changes.
 *
 * The tests verify only static layout constants that are exported from the UI
 * components and navigation configuration. This avoids any dependency on a UI
 * rendering library that is not present in the project.
 *
 * Expected exports (added as part of the fix):
 *   - src/components/ui/SimpleAddButtons.tsx      → export const simpleAddButtonsStyle
 *   - src/components/ui/ReceiptSavedSnackbar.tsx → export const receiptSavedSnackbarStyle
 *   - src/screens/DashboardScreen.tsx           → export const recentActivityContainerStyle
 *   - src/navigation/constants.ts               → export const BOTTOM_TAB_LABELS
 *
 * All values are compared against the design requirements for a 390 × 844 dp
 * phone screen.
 */

import { simpleAddButtonsStyle } from '../../src/components/ui/SimpleAddButtons';
import { receiptSavedSnackbarStyle } from '../../src/components/ui/ReceiptSavedSnackbar';
import { recentActivityContainerStyle } from '../../src/screens/DashboardScreen';
import { BOTTOM_TAB_LABELS } from '../../src/navigation/constants';

describe('Dashboard layout constants', () => {
  // The bottom tab bar is 56 dp high; with a typical safe‑area inset (≈16 dp)
  // the FAB container and snackbar must sit at least 72 dp above the screen bottom.
  const MIN_BOTTOM_OFFSET = 72;

  // The recent‑activity list must have enough bottom padding to keep the last
  // row visible above the FABs. The design calls for ≥ 80 dp.
  const MIN_SCROLL_PADDING_BOTTOM = 80;

  test('SimpleAddButtons is absolutely positioned above the tab bar', () => {
    expect(simpleAddButtonsStyle.position).toBe('absolute');
    expect(simpleAddButtonsStyle.bottom).toBeGreaterThanOrEqual(MIN_BOTTOM_OFFSET);
  });

  test('ReceiptSavedSnackbar is absolutely positioned above the tab bar', () => {
    expect(receiptSavedSnackbarStyle.position).toBe('absolute');
    expect(receiptSavedSnackbarStyle.bottom).toBeGreaterThanOrEqual(MIN_BOTTOM_OFFSET);
  });

  test('Recent‑activity ScrollView padding prevents overlap with FABs', () => {
    expect(recentActivityContainerStyle.paddingBottom).toBeGreaterThanOrEqual(
      MIN_SCROLL_PADDING_BOTTOM
    );
  });

  test('Bottom tab bar contains the required labels', () => {
    const expected = ['Dashboard', 'Receipts', 'Mileage', 'Settings'];
    expect(BOTTOM_TAB_LABELS).toEqual(expected);
  });
});
